/* ------------------------------------------------------------ helpers */
function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;'); }
function icon(n){ return '<svg class="ic" aria-hidden="true"><use href="#i-' + n + '"/></svg>'; }
function cite(part, pages){
  var partLabel = part === 1 ? 'Part 01: Site exploration' : part === 2 ? 'Part 02: Recommendations & implementation' : 'Indian Mounds Drive Feasibility Study';
  var first = parseInt(String(pages).replace(/[^0-9]/g,' ').trim().split(' ')[0], 10) || 1;
  return '<div class="foot"><span><b>' + partLabel + '</b> · ' + pp(pages) + '</span><a href="' + pdfAt(first) + '" target="_blank" rel="noopener">Open in the study PDF ' + icon('external') + '</a></div>';
}
function page(id, title, sub, body, part, pages, extraClass){
  return '<article class="imd-page' + (extraClass ? ' ' + extraClass : '') + '" id="imd-' + id + '">' +
    '<div class="run">Indian Mounds Drive Feasibility Study</div>' +
    '<h3 class="t">' + title + '</h3>' + (sub ? '<p class="lede">' + sub + '</p>' : '') + body + cite(part, pages) + '</article>';
}
function bars(rows, cls){
  var max = 0; rows.forEach(function(r){ max = Math.max(max, r[1]); });
  return '<div class="imd-bars' + (cls ? ' ' + cls : '') + '">' + rows.map(function(r){
    return '<span>' + esc(r[0]) + '</span><div><i style="width:' + (r[1] / max * 78) + '%;background:' + r[2] + '" data-v="' + r[1] + '%"></i></div>';
  }).join('') + '</div>';
}
function donut(rows, inner){
  var tot = 0; rows.forEach(function(r){ tot += r[1]; });
  var R = 50, r = inner ? 28 : 0, cx = 60, cy = 60, a0 = -Math.PI / 2, out = '';
  rows.forEach(function(row){
    var a1 = a0 + row[1] / tot * Math.PI * 2, big = (a1 - a0) > Math.PI ? 1 : 0;
    var x0 = cx + R * Math.cos(a0), y0 = cy + R * Math.sin(a0), x1 = cx + R * Math.cos(a1), y1 = cy + R * Math.sin(a1);
    var d;
    if(r){ var ix0 = cx + r * Math.cos(a1), iy0 = cy + r * Math.sin(a1), ix1 = cx + r * Math.cos(a0), iy1 = cy + r * Math.sin(a0);
      d = 'M' + x0 + ' ' + y0 + 'A' + R + ' ' + R + ' 0 ' + big + ' 1 ' + x1 + ' ' + y1 + 'L' + ix0 + ' ' + iy0 + 'A' + r + ' ' + r + ' 0 ' + big + ' 0 ' + ix1 + ' ' + iy1 + 'Z'; }
    else d = 'M' + cx + ' ' + cy + 'L' + x0 + ' ' + y0 + 'A' + R + ' ' + R + ' 0 ' + big + ' 1 ' + x1 + ' ' + y1 + 'Z';
    var am = (a0 + a1) / 2, lr = r ? (R + r) / 2 : R * .62;
    out += '<path d="' + d + '" fill="' + row[2] + '" stroke="#fff" stroke-width="1.5"/>';
    if(row[1] >= 8) out += '<text x="' + (cx + lr * Math.cos(am)) + '" y="' + (cy + lr * Math.sin(am) + 3) + '" text-anchor="middle" font-size="8.5" font-weight="600" fill="#fff" font-family="Work Sans, sans-serif">' + row[1] + '%</text>';
    a0 = a1;
  });
  return '<div class="imd-donut"><svg viewBox="0 0 120 120" aria-hidden="true">' + out + '</svg><ul>' + rows.filter(function(r){ return r[0]; }).map(function(r){ return '<li><i style="background:' + r[2] + '"></i>' + esc(r[0]) + '<b>' + r[1] + '%</b></li>'; }).join('') + '</ul></div>';
}
function legend(items){
  return '<ul class="imd-legend">' + items.map(function(it){
    var sw;
    if(it[0] === 'img') sw = '<img src="' + ART + it[1] + '" alt="">';
    else if(it[0] === 'line') sw = '<i class="line" style="background:' + it[1] + '"></i>';
    else if(it[0] === 'dash') sw = '<i class="dash" style="border-color:' + it[1] + '"></i>';
    else if(it[0] === 'dot') sw = '<i class="dot" style="background:' + it[1] + '"></i>';
    else if(it[0] === 'pill') sw = '<i class="pill" style="background:' + it[1] + '"></i>';
    else if(it[0] === 'head') return '<h5>' + esc(it[1]) + '</h5>';
    else sw = '<i class="blob" style="background:' + it[1] + '"></i>';
    return '<li><span class="sw">' + sw + '</span><span><b>' + esc(it[2]) + '</b>' + (it[3] ? '<small>' + esc(it[3]) + '</small>' : '') + '</span></li>';
  }).join('') + '</ul>';
}
function list(items){ return '<ul class="plain">' + items.map(function(i){ return '<li>' + i + '</li>'; }).join('') + '</ul>'; }

