    '<div class="toc"><h3>Contents</h3><ol>' + D.toc.map(function(t){ return '<li' + (t[3] ? ' class="part"' : '') + '><span>' + t[0] + '</span><a href="#imd-' + t[2] + '">' + esc(t[1]) + '</a></li>'; }).join('') +
    '<li><span>3D</span><a href="#imd-model">The corridor and the plan in 3D</a></li><li><span>i</span><a href="#imd-sources">Sources and what is left out</a></li></ol></div></div>';
